// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// Text and icons drawn on the chat's color (header, send button, visitor
// bubbles, buttons). The Shop Assistant sets that color itself
// (secondary_color). The ticketing chat (mode "human") has only one color: it
// always sends secondary_color "#ffffff", meaning "no preference", which is
// unreadable on a light color. There the widget picks dark text instead.
// public/widget/loader.js repeats this rule for the bubble and the product
// page box (it cannot import this file).

export const DARK_TEXT = "#111827";
const WHITE = "#ffffff";
// WCAG's minimum for icons and large text: white is kept down to it, so a dark
// or medium color keeps its white text.
const MIN_WHITE_CONTRAST = 3;

// WCAG relative luminance of #rgb or #rrggbb, null for anything else.
export function relativeLuminance(color: string): number | null {
  const match = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
  if (!match) return null;
  const hex = match[1].length === 3 ? match[1].replace(/./g, "$&$&") : match[1];
  const [r, g, b] = [0, 2, 4].map((i) => {
    const c = parseInt(hex.slice(i, i + 2), 16) / 255;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}

// White unless it falls under 3:1 on `background`, then dark. A color it
// cannot read keeps white.
export function readableTextOn(background: string): string {
  const luminance = relativeLuminance(background);
  if (luminance === null) return WHITE;
  return 1.05 / (luminance + 0.05) < MIN_WHITE_CONTRAST ? DARK_TEXT : WHITE;
}

// WCAG's minimum for normal text, which the flow's 13 px button labels are.
const MIN_TEXT_CONTRAST = 4.5;

// The chat's color as text or an icon on white (the flow's buttons, the home
// screen's initial and send icon): kept when it reads at 4.5:1, else darkened
// in its own hue until it does, so a pale pink stays a pink. A color it cannot
// read is left alone.
export function readableOnWhite(color: string): string {
  const match = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(color.trim());
  if (!match) return color;
  const hex = match[1].length === 3 ? match[1].replace(/./g, "$&$&") : match[1];
  const channels = [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
  for (let keep = 1; keep > 0; keep -= 0.05) {
    const shade = `#${channels.map((c) => Math.round(c * keep).toString(16).padStart(2, "0")).join("")}`;
    if (1.05 / (relativeLuminance(shade)! + 0.05) >= MIN_TEXT_CONTRAST) return keep === 1 ? color : shade;
  }
  return DARK_TEXT;
}

function isNoPreference(color: unknown): boolean {
  return typeof color !== "string" || /^#?(fff|ffffff)$/i.test(color.trim());
}

// The configuration with a readable secondary_color: only the ticketing chat's
// without a text color of its own changes.
export function withReadableText<T extends { mode?: unknown; primary_color: string; secondary_color?: unknown }>(
  config: T
): T {
  if (config.mode !== "human" || !isNoPreference(config.secondary_color)) return config;
  return { ...config, secondary_color: readableTextOn(config.primary_color) };
}
